class SendgridNamespace:
    """Typed accessor for the `sendgrid` app. Reach it via `client.apps.sendgrid`."""

    def __init__(self, client: Keyhaven) -> None:
        self._client = client

    async def associate_domain_with_subuser(
        self,
        *,
        owner_id: str,
        account_id: str = DEFAULT_ACCOUNT_ID,
        request: SendgridAssociateDomainWithSubuserRequest | None = None,
        **fields: Any,
    ) -> Any:
        """
        Associates a specific authenticated domain with a subuser, allowing them to send emails using the parent account's authenticated domain. Use this to delegate sending authority to subusers while maintaining domain reputation. This affects the subuser's email sending capabilities.
        """
        args = (
            request.model_dump(mode="json", by_alias=True, exclude_none=True)
            if request is not None
            else dict(fields)
        )
        return await self._client.execute(
            "sendgrid.associate_domain_with_subuser", owner_id, args, account_id=account_id
        )

    async def create_branded_link(
        self,
        *,
        owner_id: str,
        account_id: str = DEFAULT_ACCOUNT_ID,
        request: SendgridCreateBrandedLinkRequest | None = None,
        **fields: Any,
    ) -> Any:
        """
        Creates a new branded link (link whitelabel) so that all click-tracked links and images in your emails appear from your domain instead of sendgrid.net. Use this to maintain brand consistency and improve deliverability. You must configure DNS records after creation.
        """
        args = (
            request.model_dump(mode="json", by_alias=True, exclude_none=True)
            if request is not None
            else dict(fields)
        )
        return await self._client.execute(
            "sendgrid.create_branded_link", owner_id, args, account_id=account_id
        )

    async def create_design(
        self,
        *,
        owner_id: str,
        account_id: str = DEFAULT_ACCOUNT_ID,
        request: SendgridCreateDesignRequest | None = None,
        **fields: Any,
    ) -> Any:
        """
        Creates a new email design in the SendGrid Design Library with HTML content, plain text, and categories. Use this to build reusable email templates. The design can later be used when sending emails. This changes the design library but does not send emails.
        """
        args = (
            request.model_dump(mode="json", by_alias=True, exclude_none=True)
            if request is not None
            else dict(fields)
        )
        return await self._client.execute(
            "sendgrid.create_design", owner_id, args, account_id=account_id
        )

    async def create_domain_authentication(
        self,
        *,
        owner_id: str,
        account_id: str = DEFAULT_ACCOUNT_ID,
        request: SendgridCreateDomainAuthenticationRequest | None = None,
        **fields: Any,
    ) -> Any:
        """
        Creates a new domain authentication (whitelabel) configuration to verify that your SendGrid account is authorized to send emails from your domain. This generates DNS records that must be added to your DNS provider. Use this to improve email deliverability and prevent spoofing. Completing domain authentication affects how recipients see your email's from address.
        """
        args = (
            request.model_dump(mode="json", by_alias=True, exclude_none=True)
            if request is not None
            else dict(fields)
        )
        return await self._client.execute(
            "sendgrid.create_domain_authentication", owner_id, args, account_id=account_id
        )

